    'hotel-safety-essentials' => 
    array (
      'title' => 'Mahahalagang Kaalaman sa Kaligtasan sa Hotel',
      'short_description' => 'Ang safety training na kailangan ng bawat empleyado ng hotel anuman ang departamento.',
